/** WKS-B04SISTEMA: bloque de entrada y salida de los entry points B04SISTEM y MANTB04SISTEM. */
public record SistemaControl(
        int funcion,            // 9(02): 1 consulta, 37 cambio
        int sistema,            // 9(04)
        int producto,           // 9(04)  requerido por la consulta según el comentario del copy
        int instrumento,        // 9(04)  idem
        String nombreCorto,     // X(20)
        String nombreLargo,     // X(40)
        int estatus) {          // 9(02)  estado del sistema en B04SISTEM

    public SistemaControl conEstatus(int nuevo) {
        return new SistemaControl(37, sistema, producto, instrumento, nombreCorto, nombreLargo, nuevo);
    }
}

/** Puerto hacia la librería de control (S151L001CTL); en la nube, un servicio REST o JPA. */
public interface LibreriaControl {
    ResultadoLibCtl consultaSistema(int sistema, int producto, int instrumento);   // B04SISTEM, función 1
    ResultadoLibCtl cambiaSistema(SistemaControl registro);                        // MANTB04SISTEM, función 37
}
public record ResultadoLibCtl(long codigo, SistemaControl registro) {
    public boolean ok() { return codigo == 0; }
}

/** WKS-PARAMETROS: lo que la WFL pasa al programa. */
public record CambioEstadoParams(
        @Min(0) @Max(999) int sistema,     // WKS-PARAM-SISTEMA 9(03)
        @Min(0) @Max(99)  int estatus) {   // WKS-PARAM-ESTATUS 9(02)

    static CambioEstadoParams de(JobParameters p) {
        return new CambioEstadoParams(
                p.getLong("sistema").intValue(),
                p.getLong("estatus").intValue());
    }
}

@Component
@RequiredArgsConstructor
public class CambioEstadoSistemaTasklet implements Tasklet {   // PROGRAM-ID CALLLIBCTL (P602)

    private final LibreriaControl libCtl;
    private final ReporteOperador operador;     // LJ IN LIB-DISP: S0151/P602/002

    @Override
    public RepeatStatus execute(StepContribution contribution, ChunkContext ctx) {
        var p = CambioEstadoParams.de(ctx.getStepContext().getStepExecution().getJobParameters());
        var consulta = libCtl.consultaSistema(p.sistema(), 0, 0);       // 000300, primera parte
        if (!consulta.ok()) operador.info(51001, "ERROR AL CONSULTAR B04");
        var cambio = libCtl.cambiaSistema(base(consulta, p).conEstatus(p.estatus()));
        if (!cambio.ok()) operador.info(51001, "ERROR AL ACTUALIZAR B04");
        // STOP RUN: el fuente termina normal aunque ambas llamadas fallen.
        contribution.setExitStatus(cambio.ok() ? ExitStatus.COMPLETED
                                               : new ExitStatus("COMPLETED_WITH_ERRORS"));
        return RepeatStatus.FINISHED;
    }
}

